import { test, expect } from '@playwright/test';

test.describe('File Upload Organization', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display file upload interface with folder organization', async ({ page }) => {
    // Check if the upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Check if folder structure is visible
    const folderSection = page.getByRole('region', { name: /folders/i });
    await expect(folderSection).toBeVisible();
  });

  test('should organize uploaded files into folders', async ({ page }) => {
    // Create a new folder
    const createFolderButton = page.getByRole('button', { name: /create folder/i });
    await createFolderButton.click();

    // Enter folder name
    const folderNameInput = page.getByLabel(/folder name/i);
    await folderNameInput.fill('Documents');

    // Confirm folder creation
    const confirmButton = page.getByRole('button', { name: /confirm|create/i });
    await confirmButton.click();

    // Verify folder was created
    const newFolder = page.getByText('Documents');
    await expect(newFolder).toBeVisible();
  });

  test('should upload file to selected folder', async ({ page }) => {
    // Select a folder first
    const folderItem = page.getByRole('treeitem', { name: /documents/i });
    await folderItem.click();

    // Click upload button
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Set input file
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles('test-file.txt');

    // Wait for upload to complete
    const uploadSuccess = page.getByText(/upload successful|file uploaded/i);
    await expect(uploadSuccess).toBeVisible({ timeout: 5000 });

    // Verify file appears in the folder
    const uploadedFile = page.getByText('test-file.txt');
    await expect(uploadedFile).toBeVisible();
  });

  test('should display files organized by folder structure', async ({ page }) => {
    // Check if folder tree is visible
    const folderTree = page.getByRole('tree');
    await expect(folderTree).toBeVisible();

    // Expand a folder to see files
    const expandButton = page.getByRole('button', { name: /expand|show files/i }).first();
    await expandButton.click();

    // Verify files are displayed under the folder
    const fileList = page.getByRole('list', { name: /files/i });
    await expect(fileList).toBeVisible();
  });

  test('should move file between folders', async ({ page }) => {
    // Right-click on a file to open context menu
    const fileItem = page.getByText('test-file.txt');
    await fileItem.click({ button: 'right' });

    // Select move option
    const moveOption = page.getByRole('menuitem', { name: /move/i });
    await expect(moveOption).toBeVisible();
    await moveOption.click();

    // Select destination folder
    const destinationFolder = page.getByRole('option', { name: /archive/i });
    await destinationFolder.click();

    // Confirm move
    const confirmButton = page.getByRole('button', { name: /confirm|move/i });
    await confirmButton.click();

    // Verify file is no longer in original location
    const originalLocation = page.getByRole('treeitem', { name: /documents/i });
    await originalLocation.click();
    const movedFile = page.getByText('test-file.txt');
    await expect(movedFile).not.toBeVisible();
  });
});
